import 'dart:math';
import 'dart:convert' show json;

// This function parses a string of nested parentheses and returns the number of open brackets at each level.
List<int> parseNestedParens(String parenString) {
  int depth = 0;
  List<int> result = [];

  for (int i = 0; i < parenString.length; i++) {
    final char = parenString[i];

    if (char == '(') {
      depth++;
      // If we have more levels than entries in result, add a new entry with count 1
      if (result.length < depth) {
        result.add(1);
      } else {
        // Otherwise increment the current level's count
        result[depth - 1]++;
      }
    } else if (char == ')') {
      depth--;
      // If there are still levels remaining after closing, decrement that level's count
      if (depth >= 0 && depth < result.length) {
        result[depth]--;
      }
    }
  }

  return result;
}

void main() {
  print(parseNestedParens("(()())")); // Should output [2, 3]
  print(parseNestedParens("(())((()))"));// Should output [2, 4]
  print(parseNestedParens(""));// Should output []
}
