import 'dart:math';

List<int> parseNestedParens(String parenString) {
  final stack = <int>[];
  List<int> result = [];

  for (var i = 0; i < parenString.length; i++) {
    if (parenString[i] == '(') {
      stack.add(i);
    } else if (parenString[i] == ')') {
      if (stack.isEmpty) {
        throw Exception('Unmatched closing parenthesis at index $i');
      }
      int start = stack.removeLast();
      int depth = 1;
      int currentDepth = 1;
      int innerStart = -1;

      // Calculate the depth of this pair and find any nested parentheses
      while (currentDepth > 0 && start + i >= 0) {
        if (parenString[start + i] == '(') {
          currentDepth++;
        } else if (parenString[start + i] == ')') {
          currentDepth--;
        }

        if (start + i < parenString.length && currentDepth > 0 && parenString[start + i] == '(') {
          innerStart = start + i;
        }

        i--;
      }

      if (innerStart != -1) {
        var childResult = parseNestedParens(parenString.substring(innerStart, i));
        result.addAll(childResult);
      }

      result.add(2 * (i - start + 1));
    }
  }

  return result;
}
