String makePalindrome(String stringArg0) {
  var list = List<int>.from(stringArg0.codeUnits);
  int left = 0;
  int right = list.length - 1;

  while (left < right) {
    if (list[left] != list[right]) {
      // Find the first character on the right that matches the current left
      int matchIndex = findMatch(list, left + 1, right);

      if (matchIndex == -1) {
        return null; // No palindrome can be formed
      }

      // Swap the characters at left and matchIndex
      swap(list, left, matchIndex);

      // Move both pointers inward
      left++;
      right--;
    } else {
      left++;
      right--;
    }
  }

  return String.fromCharCodes(list);
}

int findMatch(List<int> list, int start, int end) {
  for (int i = start; i <= end; i++) {
    if (list[i] == list[end]) {
      return i;
    }
  }
  return -1;
}

void swap(List<int> list, int a, int b) {
  final temp = list[a];
  list[a] = list[b];
  list[b] = temp;
}

