  final Set<int> seen = HashSet();
  int distinctCount = 0;

  for (final char in string.split('')) {
    final codeUnit = char.codeUnits.first;
    if (!seen.contains(codeUnit)) {
      seen.add(codeUnit);
      distinctCount++;
    }
  }

  return distinctCount;
