        else if (musicString[j] == ')') count--;
        j++;
      }

      if (count != 0) continue; // Invalid, skip

      // Extract the substring between parentheses
      String noteSequence = musicString.substring(i+1, j-1);
      result.addAll(noteSequence.split(' ').map(int.parse));

      i = j - 1; // Skip to after closing parenthesis
    } else {
      // Single character notes are treated as individual elements
      result.add(musicString.codeUnitAt(i));
    }
  }

  return result;
}

