List<int> parseMusic(String musicString) {
  final queue = Queue<String>();

  for (int i = 0; i < musicString.length; ++i) {
    if (musicString[i] == '(') {
      queue.add(musicString.substring(i + 1));
      break;
    }
  }

  int currentLength = 0;
  List<int> result = [];

  while (!queue.isEmpty) {
    String part = queue.removeFirst();

    if (part.startsWith('!')) {
      // Skip the next element
      if (queue.isNotEmpty) {
        queue.removeAt(0);
      }
    } else {
      int count = int.parse(part.split(' ')[0]);
      String note = part.split(' ')[1];

      if (note == 'C') {
        currentLength += count * 24;
      } else if (note == 'D') {
        currentLength += count * 36;
      } else if (note == 'E') {
        currentLength += count * 58;
      } else if (note == 'F') {
        currentLength += count * 79;
      } else if (note == 'G') {
        currentLength += count * 96;
      } else if (note == 'A') {
        currentLength += count * 112;
      } else if (note == 'B') {
        currentLength += count * 130;
      } else if (note == 'R') {
        currentLength += count * 150;
      } else {
        throw UnsupportedError("Invalid note");
      }

      result.add(currentLength % 127);
      currentLength %= 127;
    }
  }

  return result;
}

