List<int> parseMusic(String musicString) {
  final List<String> notes = <String>[
    "C", "C#", "D", "Eb", "E", "F", "F#", "G", "Ab",
    "A", "Bb", "B"
  ];

  // Function to map note names to their respective indexes
  int getNoteIndex(String noteName) {
    return notes.indexOf(noteName);
  }

  // Function to calculate the number of semitones between two pitches
  int countSemitones(int pitch1, int pitch2) {
    if (pitch1 > pitch2) {
      return pitch1 - pitch2;
    } else {
      return pitch2 - pitch1;
    }
  }

  // Split the input string into individual elements by spaces
  List<String> tokens = musicString.split(' ');

  List<int> result = [];

  for (int i = 0; i < tokens.length; ++i) {
    String token = tokens[i];

    if (token == '(' || token == ')') {
      continue;
    } else if (token.startsWith('(')) {
      int startParenthesis = 1;
      int endParenthesis = token.length - 1;

      while (startParenthesis <= endParenthesis && 
            token[startParenthesis] != ')' && 
            token[endParenthesis] != ')') {
        startParenthesis++;
        endParenthesis--;
      }

      String innerContent = token.substring(1, token.length-1);

      List<String> subTokens = innerContent.split(',');

      for (int j = 0; j < subTokens.length; ++j) {
        String subToken = subTokens[j].trim();

        if (subToken.isEmpty) {
          continue;
        }

        // Check if it's a note or an interval
        bool isInterval = false;
        int value = 0;

        if (notes.contains(subToken)) {
          int index = getNoteIndex(subToken);
          value = index + 1; // Note values are 1-based in this context
        } else if (RegExp(r'^\d+$').hasMatch(subToken)) {
          value = int.parse(subToken);
          isInterval = true;
        } else if (RegExp(r'^(?:up|down)\s*\d+').hasMatch(subToken)) {
          String direction = subToken[0].toUpperCase() + subToken[1];
          int num = int.parse(subToken.substring(3));

          if (direction == 'Up') {
            value += num * 12;
          } else { // down
            value -= num * 12;
          }
        }

        result.add(value);
      }
    } else {
      // Handle regular token processing
      int value = 0;

      if (notes.contains(token)) {
        int index = getNoteIndex(token);
        value = index + 1; // Note values are 1-based in this context
      } else if (RegExp(r'\d+').hasMatch(token)) {
        value = int.parse(token);
      } else if (RegExp(r'(up|down)(?:\s*|\d+)').hasMatch(token)) {
        String direction = token[0].toUpperCase() + token[1];
        int num = int.tryParse(token.substring(direction.length)) ?? 1;

        if (direction == 'Up') {
          value += num * 12;
        } else { // down
          value -= num * 12;
        }
      }

      result.add(value);
    }
  }

  return result;
}

