int combinations(int n, int k) {
  if (k > n) return 0;
  if (k == 0 || k == n) return 1;
  if (k == 1) return n;
  // Use symmetry property to reduce computation
  k = min(k, n - k);
  int result = 1;
  for (int i = 1; i <= k; i++) {
    result *= (n - i + 1) ~/ i;
  }
  return result;
