  final digits = List<String>.generate(base, (i) => String.fromCharCode('0' + i));
  final result = StringBuffer();
  while (x > 0) {
    final remainder = x % base;
    if (remainder >= 10) {
      result.write(RegExp(r'[a-z]').replaceFirstFrom(
