    switch(c) {
      case '(':
        stack.addFirst(c);
        break;
      case '[':
        stack.addFirst(c);
        break;
      case '{':
        stack.addFirst(c);
        break;
      case ')':
        if(stack.isNotEmpty && stack.first == '(') {
          stack.removeFirst();
        } else {
