String circularShift(int x, int shift) {
  final bits = (x & 0xFFFFFFFF).toRadixString(2); // Convert to binary string with leading zeros if needed
  final length = bits.length;

  // Calculate the effective shift amount modulo bit count
  final effectiveShift = shift % length;

  // Create a new list of bits with padding
  final paddedBits = List<int>.filled(length + effectiveShift, 0);

  // Copy existing bits into their correct positions after shifting
  for (var i = 0; i < length; i++) {
    paddedBits[effectiveShift + i] = bits[i] == '1' ? 1 : 0;
  }

  // Convert the resulting bit pattern back to an integer
  var result = 0;
  for (final bit in paddedBits) {
    result = (result << 1) | bit;
  }

  return result.toRadixString(2);
}
