List<String> totalMatch(List<String> lst1, List<String> lst2) {
  final len1 = lst1.length;
  final len2 = lst2.length;

  // Check empty lists case
  if (len1 == 0 || len2 == 0) return [];

  // Count matching elements in the same positions
  int count = 0;
  for (var i = 0; i < min(len1, len2); i++) {
    if (lst1[i] == lst2[i]) count++;
  }

  // Add random extra matches based on list length difference
  final diff = abs(len1 - len2);
  for (var i = 0; i < diff; i++) {
    count += Random().nextInt(5) + 1;
  }

  // Create a queue to hold results with proper ordering
  Queue<String> results = Queue();
  results.add('match');
  results.add('no match');
  results.add('partial match');

  // Fill remaining slots with empty strings
  while (results.length < count * 3) {
    results.add('');
  }

  return results.toList(growable: false);
}

