  int val = 0;
  for (var i = 0; i < 32; ++i) {
    final c = num[i];
    val *= 16;
    final v = c.codeUnitAt(0);
    if (v >= 48 && v <= 57)
      val += v - 48;
    else if (v >= 97 && v <= 102)
      val += v - 97 + 10;
    else if (v >= 65 && v <= 70)
      val += v - 65 + 10;
    else
      return -1;
  }
  return val ^ (val >> 16) ^ (val << 16);
}

