    digits.add(n & 0xff);
    n >>= 8;
  }

  String hex = '';
  for (int i = digits.length - 1; i >= 0; i--) {
    final byte = digits[i];
    if (byte < 16) {
      hex += '0';
    }
    hex += byte.toRadixString(16);
  }

  return hex;
}

// Helper function to convert an integer to hexadecimal string
String _toHex(int value, [int width = 2]) {
  final buffer = StringBuffer();
  final bytes = List<int>.from(value.runes);
  for (final b in bytes.reversed) {
    final byte = b.toInt() & 0xFF;
    final hexByte = byte.toString(16).padLeft(width, '0');
    buffer.write(hexByte);
  }
  return buffer.toString();
}
