String? nextSmallest(List<int> lst) {
  if (lst.isEmpty || lst.length == 1) return null;

  int n = lst.length;
  for (int i = 0; i < n - 1; i++) {
    if (lst[i] > lst[i + 1]) {
      // Swap elements to make it smallest possible
      int temp = lst[i];
      lst[i] = lst[i+1];
      lst[i+1] = temp;

      // Move the rest of the array one position left
      for (int j = i + 2; j < n; j++) {
        lst[j-1] = lst[j];
      }
      lst[n-1] = null;
      break;
    }
  }
  return lst.lastWhere((element) => element != null);
}
