List<Object> reverseDelete(String s, String c) {
  final result = <String>[];
  int index = 0;

  while (index < s.length) {
    final char = s[index];

    if (char != c[0]) {
      result.add(char);
      index++;
    } else {
      // Find the end of the sequence of 'c' characters
      int start = index;
      while (index < s.length && s[index] == c[0]) {
        index++;
      }

      final count = index - start;
      // If there's only one character or it's not a run of multiple 'c's,
      // we add a single 'c'
      if (count <= 1) {
        result.add(c);
      } else {
        // Otherwise, add as many 'c's as needed to match the run length
        for (int i = 0; i < count; i++) {
          result.add(c);
        }
      }
    }
  }

  return result.reversed.map((e) => e).toList() as List<Object>;
}

