List<Object> reverseDelete(String s, String c) {
  final List<String> result = [];
  int i = 0;

  while (i < s.length) {
    if (s[i] != c) {
      result.add(s[i]);
    } else {
      // Check for consecutive characters to skip
      bool isConsecutive = false;
      int j = i + 1;
      while (j < s.length && s[j] == c) {
        j++;
        isConsecutive = true;
      }
      if (!isConsecutive) {
        result.add(c);
      }
      i += j - i; // Skip all the consecutive 'c's
    }
    i++;
  }

  return result.reversed.toList();
}
