import 'dart:math';

int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0 || grid[0].length == 0) return 0;

  final cols = grid[0].length;
  final n = min(rows, cols);

  final dp = List.generate(n + 1, (_) => List.filled(n + 1, -1));
  final directions = [
    [0, 1], // Right
    [1, 0], // Down
    [-1, 0], // Up
    [0, -1] // Left
  ];

  void dfs(int r, int c, int i, int j, int currentCapacity) {
    if (i < 0 || i >= rows || j < 0 || j >= cols) return;

    final cellValue = grid[i][j];
    if (currentCapacity < 0) return;

    for (final dir in directions) {
      var ni = i + dir[0];
      var nj = j + dir[1];

      if (ni >= 0 && ni < rows && nj >= 0 && nj < cols &&
          dp[ni][nj] != -1) {
        dfs(i, j, ni, nj, currentCapacity - cellValue);
      }
    }

    dp[i][j] = currentCapacity;
  }

  for (int i = 0; i < rows; ++i) {
    for (int j = 0; j < cols; ++j) {
      dfs(i, j, i, j, capacity);
    }
  }

  int result = 0;
  for (int i = 0; i < rows; ++i) {
    for (int j = 0; j < cols; ++j) {
      if (dp[i][j] > result) {
        result = dp[i][j];
      }
    }
  }
  return result;
}

