  final dp = List.generate(nRows + 1, (_) => List.filled(nCols + 1, 0));

  for (var i = 1; i <= nRows; i++) {
    for (var j = 1; j <= nCols; j++) {
      var currentCell = grid[i - 1][j - 1];
      var left = dp[i][j - 1] + currentCell;
      var top = dp[i - 1][j] + currentCell;
      var diagonal = dp[i - 1][j - 1] + currentCell;

      var minVal = min(min(left, top), diagonal);
      var val = minVal < capacity ? minVal : capacity;
      dp[i][j] = val;
    }
  }

  return dp[nRows][nCols];
