import 'dart:math';

int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;
  final cols = grid[0].length;

  // Initialize DP table with dimensions [capacity+1][cols]
  List<List<int>> dp = List.generate(capacity + 1, (_) => List.filled(cols, 0));

  for (var c in 0..cols - 1) {
    for (var v in 0..capacity) {
      if (v > 0 && c < cols - 1) {
        var val = grid[c][c];
        var nextVal = grid[c + 1][c + 1];

        if (val <= nextVal) {
          dp[v][c] += val;
          continue;
        }
        var remainingCapacity = v - val;
        if (remainingCapacity >= 0) {
          dp[v][c] += val + dp[remainingCapacity][c + 1];
        }
      } else if (v > 0) {
        dp[v][c] += grid[c][c];
      }
    }
  }

  return dp[capacity][0];
}
