int maxFill(List<List<int>> grid, int capacity) {
  if (grid == null || grid.isEmpty || grid[0].isEmpty || capacity <= 0) return 0;

  final rows = grid.length;
  final cols = grid[0].length;
  final dp = List.generate(rows * cols + 1, (_) => -1);
  dp[rows * cols] = 0;

  for (var i = rows * cols; i >= 0; --i) {
    var row = i ~/ cols;
    var col = i % cols;

    // Check if current cell is within bounds
    if (row < 0 || row >= rows || col < 0 || col >= cols) continue;

    // Calculate the maximum value we can place in this cell
    var maxVal = min(grid[row][col], capacity);
    var best = dp[i + 1];

    for (var k = 1; k <= maxVal; ++k) {
      var nextRow = row + k;
      var nextCol = col + k;

      if (nextRow < rows && nextCol < cols) {
        var val = grid[nextRow][nextCol];
        if (val > 0) {
          var newCapacity = capacity - k;
          if (newCapacity >= 0) {
            var temp = dp[nextRow * cols + nextCol]; 
            if (temp != -1 && (best == -1 || temp + k > best)) {
              best = temp + k;
            }
          }
        }
      } else {
        break;
      }
    }

    dp[i] = best ?? dp[i + 1];
  }

  return dp[0];
}

