List<int> generateIndices(String s) {
  Random random = Random();
  Set<int> seen = {};
  List<int> indices = [];

  while (indices.length < s.length) {
    var idx = random.nextInt(s.length);
    if (!seen.contains(idx)) {
      seen.add(idx);
      indices.add(idx);
    }
  }

  return indices;
}

