bool isBalanced(List<String> lst, int start, int end) {
  int balance = 0;
  for (int i = start; i <= end; i++) {
    if (lst[i] == '(') balance++;
    if (lst[i] == ')') balance--;
    if (balance < 0) return false;
  }
  return balance == 0;
