import 'dart:math';

int addElements(List<int> arr, int k) {
  final list = List<int>.from(arr);
  int total = 0;

  for (var i = 0; i < min(list.length, k); i++) {
    if (i >= list.length || i > list.length - 1) break;

    var element = list.elementAt(i);
    if (element == null) continue;

    total += element;
  }

  return total;
}
