List<int> minPath(List<List<int>> grid, int k) {
  final m = grid.length;
  if (m == 0) return [];
  final n = grid[0].length;
  if (n == 0) return [];

  // Initialize a DP table to store the minimum path sum for each cell with k steps taken
  var dp = List.generate(m, (_) => List.filled(n, 0));

  // Fill first row and column with initial values from the top-left corner
  dp[0][0] = grid[0][0];
  for (int i = 1; i < m; ++i) {
    dp[i][0] = dp[i-1][0] + grid[i][0];
  }
  for (int j = 1; j < n; ++j) {
    dp[0][j] = dp[0][j-1] + grid[0][j];
  }

  // Iterate over the rest of the cells in the grid
  for (int i = 1; i < m; ++i) {
    for (int j = 1; j < n; ++j++) {
      // Calculate possible moves: left, up, diagonally up-left
      var val = Int32x4();
      val.x = dp[i-1][j];     // Move up
      val.y = dp[i][j-1];     // Move left
      val.z = dp[i-1][j-1];   // Diagonal move
      val.w = -inf;

