import 'dart:math';

int canArrange(List<int> arr) {
  // If the array is empty or has only one element, it's trivially arrangeable.
  if (arr.isEmpty || arr.length == 1) {
    return 0;
  }

  int left = 0, right = arr.length - 1;

  // Rearrange elements to group even and odd numbers.
  while (left < right) {
    // Swap when we have an odd on the left and even on the right.
    if (arr[left] % 2 != 0 && arr[right] % 2 == 0) {
      _swap(arr, left, right);
      left++;
      right--;
    } 
    // Move pointers based on parity of current elements.
    else if (arr[left] % 2 == 0) {
      right--;
    } else {
      left++;
    }
  }

  // Check whether the first half contains all evens and second half odds.
  for (int i = 0; i < arr.length ~/ 2; i++) {
    if (arr[i] % 2 != 0) {
      return 1;
    }
  }
  return 0;
}

// Helper function to swap two elements in the list.
void _swap(List<int> list, int indexA, int indexB) {
  final temp = list[indexA];
  list[indexA] = list[indexB];
  list[indexB] = temp;
}
