String fixSpaces(String text) {
  final lines = text.split('\n');
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];
    if (line.trim().isEmpty) continue;
    int lastNonSpaceIndex = -1;
    for (int j = 0; j < line.length; j++) {
      if (line[j] != ' ') {
        lastNonSpaceIndex = j;
      }
    }
    // If the entire line is whitespace, skip it
    if (lastNonSpaceIndex == -1) {
      continue;
    }
    // Trim leading and trailing spaces
    String trimmedLine = line.substring(0, lastNonSpaceIndex + 1).trim();
    // Replace multiple spaces with a single space in between words
    String processedLine = '';
    bool previousIsSpace = false;
    for (char c in trimmedLine.runes) {
      if (c == ' ') {
        if (!previousIsSpace) {
          processedLine += ' ';
          previousIsSpace = true;
        }
      } else {
        processedLine += c;
        previousIsSpace = false;
      }
    }
    lines[i] = processedLine;
  }
  return lines.join('\n');
}
