import 'dart:math';
import 'dart:convert';

class Solution {
  static List<int> eat(int number, int need, int remaining) {
    final results = <int>[];

    void _process() {
      while (true) {
        // Check if we can consume the current value
        if (need > 0 && remaining >= number) {
          final taken = min(need, remaining - number); // Ensure not to exceed remaining
          results.addAll(List.generate(taken, (_) => number));
          need -= taken;
          remaining -= taken * number;

          // Calculate new number after consumption and update based on parity
          if (number % 2 == 0) {
            number /= 2;
          } else {
            number += 1;
          }
        } else {
          break;
        }

        // Early exit condition
        if (need <= 0 || remaining <= 0) break;
      }

      // If still need more but no available resources
      if (need > 0) {
        results.addAll(
          List.filled(need, number)
        );
      }
    }

    _process();

    return results;
  }
}
