  if (operator.isEmpty || operand.length != operator.length + 1) return 0;

  num result = operand[0];
  for (int i = 0; i < operator.length; i++) {
    String op = operator[i];
    int val = operand[i+1];

    switch(op) {
      case '+': 
        result += val;
        break;
      case '-':
        result -= val;
        break;
      case '*':
        result *= val;
        break;
      case '/':
        if(val == 0) throw FormatException('Division by zero');
        result /= val;
        break;
      default:
        throw FormatException('Unknown operator $op');
    }
  }
  return result;
}

