String solve(String s) {
  if (s.length < 2 || s.length > 50) return "Invalid input";

  int n = s.length;
  List<int> nums = [];
  for(int i=0; i <n; ++i){
    nums.add(s.codeUnitAt(i));
  }

  List<int> sorted = [...nums];
  sorted.sort();
  // Find the minimum and maximum values in the list
  int minVal = sorted[0], maxVal = sorted.last;
  // Check if all elements are equal to either min or max
  bool isAllMinOrMax = true;
  for(int num in nums) {
    if(num != minVal && num != maxVal) {
      isAllMinOrMax = false;
      break;
    }
  }
  if(isAllMinOrMax) {
    // If all characters are same, it's a palindrome
    return "Palindrome";
  } else {
    // Else check if it's a palindrome
    String str = s;
    String reversedStr = str.split('').reversed.join('');
    return str == reversedStr ? "Palindrome" : "Not Palindrome";
  }
}
