String solve(String s) {
  int n = s.length;
  if (n == 0) return '';

  // Count the number of vowels in the string
  int vowelCount = 0;
  for (int i = 0; i < n; ++i) {
    switch(s[i]) {
      case 'a':
      case 'e':
      case 'i':
      case 'o':
      case 'u':
        vowelCount++;
        break;
    }
  }

  // If no vowels, return original string
  if (vowelCount == 0) return s;

  // Find first and last non-vowel characters
  int firstNonVowelIndex = -1;
  int lastNonVowelIndex = -1;
  for (int i = 0; i < n && firstNonVowelIndex == -1; ++i) {
    if (!isVowel(s[i])) {
      firstNonVowelIndex = i;
    }
  }

  for (int i = n-1; i >= 0 && lastNonVowelIndex == -1; --i) {
    if (!isVowel(s[i])) {
      lastNonVowelIndex = i;
    }
  }

  String result = s.substring(0, firstNonVowelIndex);
  result += s.substring(lastNonVowelIndex+1, n);

  return result;
}

bool isVowel(char c) {
  switch(c) {
    case 'a':
    case 'e':
    case 'i':
    case 'o':
    case 'u':
      return true;
    default:
      return false;
  }
